//! Wraps mikktspace0.3.0; upstream generated algorithm includes Zlib notice.
//! Original per-corner split geometry adapter. Never substitutes naive tangents.
#[cfg(feature="material-textures")]
pub fn generate(s:&super::vertex_stream::Stream)->Result<super::vertex_stream::Stream,String>{use super::vertex_stream::{Stream,unit};s.validate()?;if s.indices.len()>100_000{return Err("Mikk max100000 triangles".into());}struct Geometry{stream:Stream,written:Vec<bool>}
impl mikktspace::Geometry for Geometry{fn num_faces(&self)->usize{self.stream.indices.len()}fn num_vertices_of_face(&self,_:usize)->usize{3}fn position(&self,f:usize,v:usize)->[f32;3]{self.stream.vertices[f*3+v].position}fn normal(&self,f:usize,v:usize)->[f32;3]{self.stream.vertices[f*3+v].normal}fn tex_coord(&self,f:usize,v:usize)->[f32;2]{self.stream.vertices[f*3+v].uv}fn set_tangent_encoded(&mut self,t:[f32;4],f:usize,v:usize){self.stream.vertices[f*3+v].tangent=t;self.written[f*3+v]=true;}}
let mut stream=Stream{vertices:Vec::with_capacity(s.indices.len()*3),indices:Vec::with_capacity(s.indices.len())};for tri in &s.indices{let a=s.vertices[tri[0] as usize].uv;let b=s.vertices[tri[1] as usize].uv;let c=s.vertices[tri[2] as usize].uv;let area=(b[0] as f64-a[0] as f64)*(c[1] as f64-a[1] as f64)-(b[1] as f64-a[1] as f64)*(c[0] as f64-a[0] as f64);if area.abs()<1e-20{return Err("normal map requires nondegenerate UV triangles".into());}let i=stream.vertices.len() as u32;stream.vertices.extend(tri.map(|i|s.vertices[i as usize]));stream.indices.push([i,i+1,i+2]);}let mut geometry=Geometry{written:vec![false;stream.vertices.len()],stream};if !mikktspace::generate_tangents(&mut geometry)||geometry.written.iter().any(|v|!*v){return Err("Mikk generation incomplete".into());}for v in &mut geometry.stream.vertices{let n=v.normal.map(|v|v as f64);let t=[v.tangent[0] as f64,v.tangent[1] as f64,v.tangent[2] as f64];let d=n.iter().zip(t).map(|(a,b)|a*b).sum::<f64>();let t=unit(std::array::from_fn(|j|t[j]-n[j]*d))?;v.tangent=[t[0] as f32,t[1] as f32,t[2] as f32,v.tangent[3]];}geometry.stream.validate()?;Ok(geometry.stream)}
#[cfg(all(test,feature="material-textures"))]mod tests{use super::*;use crate::threed::{primitives::Vertex,vertex_stream::Stream};#[test]fn mirrored_uv_handedness(){let mut s=Stream{vertices:vec![Vertex{position:[0.,0.,0.],normal:[0.,0.,1.],uv:[0.,0.],tangent:[1.,0.,0.,1.]},Vertex{position:[1.,0.,0.],normal:[0.,0.,1.],uv:[1.,0.],tangent:[1.,0.,0.,1.]},Vertex{position:[0.,1.,0.],normal:[0.,0.,1.],uv:[0.,1.],tangent:[1.,0.,0.,1.]}],indices:vec![[0,1,2]]};let a=generate(&s).unwrap();assert!(a.vertices[0].tangent[0]>0.99);assert_eq!(a.vertices[0].tangent[3],1.);s.vertices[1].uv[0]=-1.;let a=generate(&s).unwrap();assert!(a.vertices[0].tangent[0]< -0.99);assert_eq!(a.vertices[0].tangent[3],-1.);s.vertices[2].uv=[0.;2];assert!(generate(&s).is_err());}}
